fun buildPrefix(a: IntArray): LongArray {
    val prefix = LongArray(a.size + 1)       // prefix[0] = 0
    for (i in a.indices) {
        prefix[i + 1] = prefix[i] + a[i]
    }
    return prefix
}

// Sum of a[l..r] inclusive
fun rangeSum(prefix: LongArray, l: Int, r: Int): Long =
    prefix[r + 1] - prefix[l]
// Build: O(n)   Query: O(1)   Space: O(n)

fun subarraySum(nums: IntArray, k: Int): Int {
    val count = HashMap<Int, Int>()
    count[0] = 1                  // empty prefix
    var sum = 0
    var result = 0
    for (x in nums) {
        sum += x
        // we need an earlier prefix equal to (sum - k)
        result += count[sum - k] ?: 0
        count[sum] = (count[sum] ?: 0) + 1
    }
    return result
}
// Time: O(n)   Space: O(n)
// Works with negative numbers, unlike sliding window

fun applyUpdates(n: Int, updates: Array<IntArray>): IntArray {
    val diff = IntArray(n + 1)
    for ((l, r, x) in updates) {          // add x to a[l..r]
        diff[l] += x
        diff[r + 1] -= x
    }
    val result = IntArray(n)
    var running = 0
    for (i in 0 until n) {
        running += diff[i]
        result[i] = running
    }
    return result
}
// Each update: O(1)   Final rebuild: O(n)

class NumArray(nums: IntArray) {
    private val prefix = IntArray(nums.size + 1)

    init {
        for (i in nums.indices) prefix[i + 1] = prefix[i] + nums[i]
    }

    fun sumRange(left: Int, right: Int): Int =
        prefix[right + 1] - prefix[left]
}
// Constructor: O(n)   Each query: O(1)

fun pivotIndex(nums: IntArray): Int {
    val total = nums.sum()
    var left = 0
    for (i in nums.indices) {
        // right sum = total - left - nums[i]
        if (left == total - left - nums[i]) return i
        left += nums[i]
    }
    return -1
}
// Time: O(n)   Space: O(1)

fun subarraysDivByK(nums: IntArray, k: Int): Int {
    val count = IntArray(k)
    count[0] = 1
    var sum = 0
    var result = 0
    for (x in nums) {
        sum = ((sum + x) % k + k) % k      // keep remainder non-negative
        result += count[sum]
        count[sum]++
    }
    return result
}
// Time: O(n)   Space: O(k)
// Two equal remainders mean the sum between them is divisible by k

fun findMaxLength(nums: IntArray): Int {
    val firstSeen = HashMap<Int, Int>()
    firstSeen[0] = -1
    var balance = 0
    var best = 0
    for (i in nums.indices) {
        balance += if (nums[i] == 1) 1 else -1    // treat 0 as -1
        val prev = firstSeen[balance]
        if (prev != null) best = maxOf(best, i - prev)
        else firstSeen[balance] = i
    }
    return best
}
// Time: O(n)   Space: O(n)

fun productExceptSelf(nums: IntArray): IntArray {
    val n = nums.size
    val result = IntArray(n)
    result[0] = 1
    for (i in 1 until n) result[i] = result[i - 1] * nums[i - 1]   // left products
    var right = 1
    for (i in n - 1 downTo 0) {
        result[i] *= right                                          // times right products
        right *= nums[i]
    }
    return result
}
// Time: O(n)   Space: O(1) extra (output not counted)

fun checkSubarraySum(nums: IntArray, k: Int): Boolean {
    val firstSeen = HashMap<Int, Int>()
    firstSeen[0] = -1
    var sum = 0
    for (i in nums.indices) {
        sum = (sum + nums[i]) % k
        val prev = firstSeen[sum]
        if (prev != null) {
            if (i - prev >= 2) return true
        } else {
            firstSeen[sum] = i
        }
    }
    return false
}
// Time: O(n)   Space: O(min(n, k))

fun corpFlightBookings(bookings: Array<IntArray>, n: Int): IntArray {
    val diff = IntArray(n + 2)
    for ((first, last, seats) in bookings) {     // flights are 1-indexed
        diff[first] += seats
        diff[last + 1] -= seats
    }
    val result = IntArray(n)
    var running = 0
    for (i in 1..n) {
        running += diff[i]
        result[i - 1] = running
    }
    return result
}
// Time: O(n + bookings)   Space: O(n)

fun carPooling(trips: Array<IntArray>, capacity: Int): Boolean {
    val diff = IntArray(1002)
    for ((passengers, from, to) in trips) {
        diff[from] += passengers
        diff[to] -= passengers          // passengers leave at 'to'
    }
    var current = 0
    for (d in diff) {
        current += d
        if (current > capacity) return false
    }
    return true
}
// Time: O(n + 1001)   Space: O(1001)

class NumMatrix(matrix: Array<IntArray>) {
    private val prefix: Array<IntArray>

    init {
        val rows = matrix.size
        val cols = matrix[0].size
        prefix = Array(rows + 1) { IntArray(cols + 1) }
        for (r in 0 until rows) {
            for (c in 0 until cols) {
                prefix[r + 1][c + 1] = matrix[r][c] +
                    prefix[r][c + 1] + prefix[r + 1][c] - prefix[r][c]
            }
        }
    }

    fun sumRegion(r1: Int, c1: Int, r2: Int, c2: Int): Int =
        prefix[r2 + 1][c2 + 1] - prefix[r1][c2 + 1] -
        prefix[r2 + 1][c1] + prefix[r1][c1]
}
// Build: O(rows * cols)   Each query: O(1)

fun maxSubArray(nums: IntArray): Int {
    var current = nums[0]
    var best = nums[0]
    for (i in 1 until nums.size) {
        current = maxOf(nums[i], current + nums[i])   // extend or restart
        best = maxOf(best, current)
    }
    return best
}
// Time: O(n)   Space: O(1)
// Same as: best (prefix[j] - minimum earlier prefix)
